script:
button { cursor: pointer; }
button:disabled { opacity: 0.4; cursor: not-allowed; }
:focus-visible { outline: 2px solid var(--6a70d365-ff72-446b-b3ce-e700d422c404, #0B0B0C); outline-offset: 3px; }
input, textarea, select { font-family: DM Mono, monospace; }
input::placeholder, textarea::placeholder { color: var(--e1b35a3c-0189-43b5-9e2c-e295cc81f525, #8A8A8F); }
input[type="radio"] { accent-color: var(--6a70d365-ff72-446b-b3ce-e700d422c404, #0B0B0C); }
[data-shop="variant-option"][data-selected="true"] {
	background: var(--6a70d365-ff72-446b-b3ce-e700d422c404, #0B0B0C);
	color: var(--14e519f0-b9a6-4acd-ae4a-f8e5664c13fa, #FFFFFF);
	border-color: var(--6a70d365-ff72-446b-b3ce-e700d422c404, #0B0B0C);
}
[data-shop="cart-count"][data-empty="true"] { display: none; }
a[data-active="true"] {
	background: var(--6a70d365-ff72-446b-b3ce-e700d422c404, #0B0B0C);
	color: var(--14e519f0-b9a6-4acd-ae4a-f8e5664c13fa, #FFFFFF);
	border-color: var(--6a70d365-ff72-446b-b3ce-e700d422c404, #0B0B0C);
}
[data-shop="rating-star"] { cursor: pointer; }
[data-shop="rating-star"][data-selected="true"] { color: var(--6a70d365-ff72-446b-b3ce-e700d422c404, #0B0B0C); }
[data-shop="thumb"][data-selected="true"] { border-color: var(--6a70d365-ff72-446b-b3ce-e700d422c404, #0B0B0C); }
[data-shop="order-progress"] .progress-stage {
	align-items: center;
	display: flex;
	flex: 1;
	flex-direction: column;
	gap: 9px;
	position: relative;
}
[data-shop="order-progress"] .progress-stage::before {
	background: var(--89b2d9a1-4c11-45a1-8a99-099334bf7d38, #E4E4E7);
	content: "";
	height: 1px;
	position: absolute;
	right: 50%;
	top: 4px;
	width: 100%;
}
[data-shop="order-progress"] .progress-stage:first-child::before { display: none; }
[data-shop="order-progress"] .progress-stage[data-done="true"]::before { background: var(--6a70d365-ff72-446b-b3ce-e700d422c404, #0B0B0C); }
.progress-stage .stage-dot {
	background: var(--14e519f0-b9a6-4acd-ae4a-f8e5664c13fa, #FFFFFF);
	border: 1px solid var(--89b2d9a1-4c11-45a1-8a99-099334bf7d38, #E4E4E7);
	border-radius: 50%;
	height: 9px;
	position: relative;
	width: 9px;
	z-index: 1;
}
.progress-stage[data-done="true"] .stage-dot { background: var(--6a70d365-ff72-446b-b3ce-e700d422c404, #0B0B0C); border-color: var(--6a70d365-ff72-446b-b3ce-e700d422c404, #0B0B0C); }
.progress-stage .stage-label {
	color: var(--e1b35a3c-0189-43b5-9e2c-e295cc81f525, #8A8A8F);
	font-family: DM Mono, monospace;
	font-size: 10px;
	letter-spacing: 0.08em;
	text-align: center;
	text-transform: uppercase;
}
.progress-stage[data-done="true"] .stage-label { color: var(--6a70d365-ff72-446b-b3ce-e700d422c404, #0B0B0C); }
[data-shop="cart-drawer"] {
	position: fixed;
	inset: 0;
	z-index: 90;
	pointer-events: none;
}
[data-shop="cart-drawer"] .drawer-backdrop {
	position: absolute;
	inset: 0;
	background: rgba(0, 0, 0, 0.45);
	display: none;
}
[data-shop="cart-drawer"] .drawer-panel {
	position: absolute;
	top: 0;
	right: 0;
	height: 100%;
	width: min(420px, 100vw);
	background: var(--14e519f0-b9a6-4acd-ae4a-f8e5664c13fa, #FFFFFF);
	color: var(--6a70d365-ff72-446b-b3ce-e700d422c404, #0B0B0C);
	display: none;
	flex-direction: column;
}
[data-shop="cart-drawer"][data-open="true"] { pointer-events: auto; }
[data-shop="cart-drawer"][data-open="true"] .drawer-backdrop { display: block; }
[data-shop="cart-drawer"][data-open="true"] .drawer-panel { display: flex; }
.drawer-header {
	align-items: center;
	border-bottom: 1px solid var(--89b2d9a1-4c11-45a1-8a99-099334bf7d38, #E4E4E7);
	display: flex;
	flex-shrink: 0;
	justify-content: space-between;
	padding: 20px 24px;
}
.drawer-title {
	font-family: DM Mono, monospace;
	font-size: 12px;
	letter-spacing: 0.12em;
	text-transform: uppercase;
}
.drawer-close {
	background: none;
	border: 0;
	color: var(--6a70d365-ff72-446b-b3ce-e700d422c404, #0B0B0C);
	font-size: 20px;
	line-height: 1;
	padding: 2px 6px;
}
.drawer-items { flex: 1; overflow-y: auto; padding: 4px 24px; }
.drawer-item {
	align-items: flex-start;
	border-bottom: 1px solid var(--89b2d9a1-4c11-45a1-8a99-099334bf7d38, #E4E4E7);
	display: flex;
	gap: 14px;
	padding: 18px 0;
}
.drawer-item:last-child { border-bottom: 0; }
.drawer-thumb {
	background: var(--c1682560-a9a1-4a76-9e0e-778bfca1f2e5, #F3F3F4);
	border-radius: 10px;
	flex-shrink: 0;
	height: 64px;
	object-fit: cover;
	width: 64px;
}
.drawer-info { display: flex; flex: 1; flex-direction: column; gap: 4px; min-width: 0; }
.drawer-name {
	color: var(--6a70d365-ff72-446b-b3ce-e700d422c404, #0B0B0C);
	font-size: 13px;
	font-weight: 500;
	line-height: 1.45;
	text-decoration: none;
}
.drawer-rate {
	color: var(--e1b35a3c-0189-43b5-9e2c-e295cc81f525, #8A8A8F);
	font-family: DM Mono, monospace;
	font-size: 11px;
	letter-spacing: 0.04em;
}
.drawer-qty { align-items: center; display: flex; gap: 8px; margin-top: 8px; }
.drawer-qty > button {
	align-items: center;
	background: var(--14e519f0-b9a6-4acd-ae4a-f8e5664c13fa, #FFFFFF);
	border: 1px solid var(--89b2d9a1-4c11-45a1-8a99-099334bf7d38, #E4E4E7);
	border-radius: 999px;
	color: var(--6a70d365-ff72-446b-b3ce-e700d422c404, #0B0B0C);
	display: flex;
	font-size: 13px;
	height: 26px;
	justify-content: center;
	width: 26px;
}
.drawer-qty > span {
	font-family: DM Mono, monospace;
	font-size: 12px;
	min-width: 16px;
	text-align: center;
}
.drawer-qty > .drawer-remove {
	background: none;
	border: 0;
	color: var(--e1b35a3c-0189-43b5-9e2c-e295cc81f525, #8A8A8F);
	font-family: DM Mono, monospace;
	font-size: 10px;
	height: auto;
	letter-spacing: 0.1em;
	margin-left: 8px;
	padding: 0;
	text-transform: uppercase;
	width: auto;
}
.drawer-amount {
	flex-shrink: 0;
	font-family: DM Mono, monospace;
	font-size: 12px;
	font-weight: 500;
}
.drawer-empty {
	color: var(--e1b35a3c-0189-43b5-9e2c-e295cc81f525, #8A8A8F);
	font-family: DM Mono, monospace;
	font-size: 12px;
	letter-spacing: 0.08em;
	padding: 48px 0;
	text-align: center;
	text-transform: uppercase;
}
.drawer-footer {
	border-top: 1px solid var(--89b2d9a1-4c11-45a1-8a99-099334bf7d38, #E4E4E7);
	display: flex;
	flex-direction: column;
	flex-shrink: 0;
	gap: 12px;
	padding: 18px 24px 22px;
}
.drawer-total-row {
	align-items: baseline;
	display: flex;
	font-family: DM Mono, monospace;
	font-size: 13px;
	justify-content: space-between;
	letter-spacing: 0.06em;
	text-transform: uppercase;
}
.drawer-note {
	color: var(--e1b35a3c-0189-43b5-9e2c-e295cc81f525, #8A8A8F);
	font-size: 11px;
	line-height: 1.5;
	margin-top: -6px;
}
.drawer-actions { display: grid; gap: 10px; grid-template-columns: 1fr 1fr; }
.drawer-view, .drawer-checkout {
	border-radius: 999px;
	font-family: DM Mono, monospace;
	font-size: 11px;
	letter-spacing: 0.12em;
	padding: 13px 16px;
	text-align: center;
	text-decoration: none;
	text-transform: uppercase;
}
.drawer-view {
	border: 1px solid var(--6a70d365-ff72-446b-b3ce-e700d422c404, #0B0B0C);
	color: var(--6a70d365-ff72-446b-b3ce-e700d422c404, #0B0B0C);
}
.drawer-checkout {
	background: var(--6a70d365-ff72-446b-b3ce-e700d422c404, #0B0B0C);
	border: 1px solid var(--6a70d365-ff72-446b-b3ce-e700d422c404, #0B0B0C);
	color: var(--14e519f0-b9a6-4acd-ae4a-f8e5664c13fa, #FFFFFF);
}
.pdp-buybar {
	bottom: 18px;
	display: flex;
	justify-content: center;
	left: 0;
	padding: 0 20px;
	position: fixed;
	right: 0;
	z-index: 80;
}
.pdp-buybar[data-visible="false"] { display: none; }
.pdp-buybar-inner {
	align-items: center;
	background: var(--14e519f0-b9a6-4acd-ae4a-f8e5664c13fa, #FFFFFF);
	border: 1px solid var(--89b2d9a1-4c11-45a1-8a99-099334bf7d38, #E4E4E7);
	border-radius: 999px;
	display: flex;
	gap: 20px;
	justify-content: space-between;
	padding: 10px 10px 10px 24px;
	width: fit-content;
}
@media (max-width: 640px) {
	.pdp-buybar { bottom: 0; padding: 0 12px 10px; }
	.pdp-buybar-inner { width: 100%; }
	[data-shop="qty-inc"], [data-shop="qty-dec"], [data-drawer-step] { min-height: 36px; min-width: 36px; }
	.drawer-close { padding: 10px; margin: -10px; }
	[data-shop="remove"], .drawer-remove { padding: 8px 6px; }
}
#reviews { scroll-margin-top: 100px; }
